const exportToExcel = () => {
  try {
    // Calculate total cost (same as printReport)
    const totalCost = items.value.reduce((sum, item) => {
      const cost =
        typeof item.cost === "string"
          ? parseFloat(item.cost.replace(/,/g, ""))
          : item.cost;
      return sum + (isNaN(cost) ? 0 : cost);
    }, 0);

    const groupLabel =
      activeGroupId.value === "1"
        ? "LOCAL PURCHASE ORDERS"
        : activeGroupId.value === "4"
        ? "PAYMENT VOUCHERS"
        : (approvalGroup.value?.group?.toUpperCase() || "APPROVAL") + " REPORT";

    // ── Company header rows ──────────────────────────────────────────
    const headerRows = [
      ["COPEX CONTRACTORS CO.LTD"],
      ["Address: Msamvu, P.O.BOX 678, Morogoro"],
      ["Tel: 0713 000 777, 0657 111 555"],
      ["Email: info@copexcontractors.co.tz"],
      ["TIN: 135-489-247   VRN: 40-032826C"],
      [],
      [groupLabel],
      [`Generated: ${new Date().toLocaleString()}`],
      [`Generated By: ${JSON.parse(localStorage.getItem("user")).name}`],
      [],
    ];

    // ── Column headers ───────────────────────────────────────────────
    const columns = [
      "S/No.",
      "Order No",
      "Purpose",
      "Type",
      "Requester",
      "Project",
      "Status",
      "Date",
      "Awaits",
      "Cost",
    ];

    // ── Data rows ────────────────────────────────────────────────────
    const dataRows = items.value.map((item, index) => [
      index + 1,
      item.order || "N/A",
      item.purpose || "N/A",
      item.type || "N/A",
      item.requester || "N/A",
      item.project || "N/A",
      item.status?.name || "N/A",
      item.date || "N/A",
      item.awaits || "N/A",
      typeof item.cost === "string"
        ? parseFloat(item.cost.replace(/,/g, "")) || 0
        : item.cost || 0,
    ]);

    // ── Total row ────────────────────────────────────────────────────
    const totalRow = ["", "", "", "", "", "", "", "", "TOTAL:", totalCost];

    // ── Assemble all rows ────────────────────────────────────────────
    const allRows = [...headerRows, columns, ...dataRows, totalRow];

    // ── Create worksheet ─────────────────────────────────────────────
    const ws = XLSX.utils.aoa_to_sheet(allRows);

    // ── Column widths ────────────────────────────────────────────────
    ws["!cols"] = [
      { wch: 6 }, // S/No.
      { wch: 10 }, // Order No
      { wch: 20 }, // Purpose
      { wch: 20 }, // Type
      { wch: 20 }, // Requester
      { wch: 25 }, // Project
      { wch: 12 }, // Status
      { wch: 12 }, // Date
      { wch: 20 }, // Awaits
      { wch: 15 }, // Cost
    ];

    // ── Style: bold company title (row 0) ────────────────────────────
    if (ws["A1"]) ws["A1"].s = { font: { bold: true, sz: 14 } };

    // ── Style: bold group label (row 7) ─────────────────────────────
    if (ws["A7"]) ws["A7"].s = { font: { bold: true, sz: 12 } };

    // ── Style: bold column headers ───────────────────────────────────
    const headerRowIndex = headerRows.length; // 0-based row of columns row
    columns.forEach((_, colIndex) => {
      const cellAddress = XLSX.utils.encode_cell({ r: headerRowIndex, c: colIndex });
      if (ws[cellAddress]) {
        ws[cellAddress].s = {
          font: { bold: true },
          fill: { fgColor: { rgb: "D3D3D3" } },
          alignment: { horizontal: "center" },
        };
      }
    });

    // ── Style: bold total row ────────────────────────────────────────
    const totalRowIndex = headerRows.length + 1 + dataRows.length;
    columns.forEach((_, colIndex) => {
      const cellAddress = XLSX.utils.encode_cell({ r: totalRowIndex, c: colIndex });
      if (ws[cellAddress]) {
        ws[cellAddress].s = { font: { bold: true } };
      }
    });

    // ── Create workbook & download ───────────────────────────────────
